#include <iostream>
#include <string>
using namespace std;

const string BLOCKS[3] = {"AA", "AB", "BB"};
string memo[11][11][11][4];
bool done[11][11][11][4];

// Longest valid continuation with counts (a, b, c) left after last block s (0 = nothing yet).
string best(int a, int b, int c, int s) {
    if (done[a][b][c][s]) return memo[a][b][c][s];
    string answer;
    int counts[3] = {a, b, c};
    string suffix = s ? BLOCKS[s - 1] : "";
    for (int i = 0; i < 3; i++) {
        if (!counts[i]) continue;
        string boundary = suffix + BLOCKS[i];
        if (boundary.find("AAA") != string::npos || boundary.find("BBB") != string::npos) continue;
        int r[3] = {a, b, c};
        r[i]--;
        string candidate = BLOCKS[i] + best(r[0], r[1], r[2], i + 1);
        if (candidate.size() > answer.size() || (candidate.size() == answer.size() && candidate < answer))
            answer = candidate;
    }
    done[a][b][c][s] = true;
    return memo[a][b][c][s] = answer;
}

int main() {
    int a, b, c;
    cin >> a >> b >> c;
    cout << best(a, b, c, 0) << '\n';
}

import java.io.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static final String[] BLOCKS = {"AA", "AB", "BB"};
    static String[][][][] memo = new String[11][11][11][4];

    // Longest valid continuation with counts (a, b, c) left after last block s (0 = nothing yet).
    static String best(int a, int b, int c, int s) {
        if (memo[a][b][c][s] != null) return memo[a][b][c][s];
        String answer = "";
        int[] counts = {a, b, c};
        String suffix = s == 0 ? "" : BLOCKS[s - 1];
        for (int i = 0; i < 3; i++) {
            if (counts[i] == 0) continue;
            String boundary = suffix + BLOCKS[i];
            if (boundary.contains("AAA") || boundary.contains("BBB")) continue;
            int[] r = {a, b, c};
            r[i]--;
            String candidate = BLOCKS[i] + best(r[0], r[1], r[2], i + 1);
            if (candidate.length() > answer.length()
                    || (candidate.length() == answer.length() && candidate.compareTo(answer) < 0))
                answer = candidate;
        }
        return memo[a][b][c][s] = answer;
    }

    public static void main(String[] args) throws IOException {
        int a = (int) nextLong(), b = (int) nextLong(), c = (int) nextLong();
        System.out.println(best(a, b, c, 0));
    }
}

package main

import (
	"fmt"
	"strings"
)

var blocks = [3]string{"AA", "AB", "BB"}
var memo [11][11][11][4]*string

// Longest valid continuation with counts (a, b, c) left after last block s (0 = nothing yet).
func best(a, b, c, s int) string {
	if memo[a][b][c][s] != nil {
		return *memo[a][b][c][s]
	}
	answer := ""
	counts := [3]int{a, b, c}
	suffix := ""
	if s > 0 {
		suffix = blocks[s-1]
	}
	for i := 0; i < 3; i++ {
		if counts[i] == 0 {
			continue
		}
		boundary := suffix + blocks[i]
		if strings.Contains(boundary, "AAA") || strings.Contains(boundary, "BBB") {
			continue
		}
		r := counts
		r[i]--
		candidate := blocks[i] + best(r[0], r[1], r[2], i+1)
		if len(candidate) > len(answer) || (len(candidate) == len(answer) && candidate < answer) {
			answer = candidate
		}
	}
	memo[a][b][c][s] = &answer
	return answer
}

func main() {
	var a, b, c int
	fmt.Scan(&a, &b, &c)
	fmt.Println(best(a, b, c, 0))
}
